import { sanitizeForPreview } from "../../utils/sanitize";

interface PreviewProps {
  html: string;
  /** Show the whole content without an inner scroll (example page). */
  fullHeight?: boolean;
}

export function Preview({ html, fullHeight = false }: PreviewProps) {
  const safe = sanitizeForPreview(html);
  const size = fullHeight ? "" : "mcb-scroll max-h-[70vh] min-h-72 overflow-auto";
  return (
    <div
      className={`mcb-preview ${size} rounded-xl border border-line bg-white p-4 sm:p-6`}
      // The HTML is generated by our own templates (all user input is
      // escaped) and additionally sanitized with DOMPurify before injection.
      dangerouslySetInnerHTML={{ __html: safe }}
    />
  );
}
